def max_sum_increasing_subseq(arr, n, i, k):
    best = [0] * (i + 1)
    for j in range(i + 1):
        best[j] = arr[j]
        for p in range(j):
            if arr[p] < arr[j] and best[p] + arr[j] > best[j]:
                best[j] = best[p] + arr[j]
    ans = arr[k]
    for j in range(i + 1):
        if arr[j] < arr[k] and best[j] + arr[k] > ans:
            ans = best[j] + arr[k]
    return ans
```

