def check_expression(expression):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in expression:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack.pop() != pairs[ch]:
                return False
        else:
            return False
    return not stack
```

